import re,collections
p='/app/text.gcode'
obj=None
z=0
data=collections.defaultdict(lambda: collections.defaultdict(list))
for ln,line in enumerate(open(p),1):
    s=line.strip()
    if s.startswith('M486 S'):
        val=s[6:]
        obj=None if val=='-1' else val
    elif s.startswith('G0') or s.startswith('G1'):
        m=re.match(r'G[01]\s+(.*)',s)
        if m:
            d=dict(re.findall(r'([XYZE])(-?\d+\.?\d*)',m.group(1)))
            if 'Z' in d: z=float(d['Z'])
            if obj is not None and 'X' in d and 'Y' in d:
                data[obj][round(z,2)].append((float(d['X']),float(d['Y'])))
for o in sorted(data):
    zs=sorted(data[o])
    print('object',o,'layers',len(zs),'zrange',zs[0],zs[-1])
    for zz in zs[:5]+zs[-5:]:
        pts=data[o][zz]
        xs=[x for x,y in pts];ys=[y for x,y in pts]
        print('  z',zz,'n',len(pts),'x',round(min(xs),1),round(max(xs),1),'y',round(min(ys),1),round(max(ys),1))
